  }
  const spot = pointOnRim(state, 230);
  const enemy = spawnEnemy(state, kind, spot.x, spot.y);
  if (enemy !== null) spawnRing(state, spot.x, spot.y, kind === KIND_TURRET ? 2 : 1, enemy.radius * 2.2, 0.5);
