      title: `WAVE ${state.waveIndex + 1} CLEARED`,
      text: `+${SCORE.waveClear}`,
      sub: 'The drift thins. Repair the hull, restock the ion cells.',
      timer: WAVE.cleared + 0.8,
      total: WAVE.cleared + 0.8,
      tone: 1,
    };
