    unlock,
    /** Play a named voice; unknown names are ignored so a typo can never break a frame. */
    play(name) {
      if (context === null || muted) return;
      const sound = SOUNDS[name];
      if (sound !== undefined) sound();
    },
    toggleMute() {
      muted = !muted;
      if (master !== null) master.gain.value = muted ? 0 : 0.55;
      return muted;
    },
    isMuted() {
      return muted;
    },
    isReady() {
      return context !== null;
    },
  };
}
